function equipmentToggleNextTargetStatus(type="设备停用"){
  return type==="设备启用" ? "使用中" : "停用";
}

function equipmentToggleActionLabel(type="设备停用"){
  return type==="设备启用" ? "启用" : "停用";
}

function equipmentToggleEligibleDevices(){
  const allowedState=activeToggleApplyType==="设备启用" ? "停用" : "使用中";
  return repairDeviceOptions.filter(device=>device.state===allowedState);
}

function ensureToggleSelectedDevice(){
  const eligible=equipmentToggleEligibleDevices();
  if(!eligible.length){
    selectedToggleDeviceIndex=-1;
    return null;
  }
  const selected=repairDeviceOptions[selectedToggleDeviceIndex];
  if(!selected || selected.state!==eligible[0].state){
    selectedToggleDeviceIndex=repairDeviceOptions.indexOf(eligible[0]);
  }
  const current=repairDeviceOptions[selectedToggleDeviceIndex];
  if(current && current.state===eligible[0].state)return current;
  selectedToggleDeviceIndex=repairDeviceOptions.indexOf(eligible[0]);
  return repairDeviceOptions[selectedToggleDeviceIndex] || null;
}

function equipmentToggleSelectedDevice(){
  return ensureToggleSelectedDevice();
}

function syncEquipmentToggleRows(){
  const cfg=configs["equipment:设备启停管理"];
  if(!cfg)return;
  cfg.rows=equipmentToggleApplicationStore
    .slice()
    .sort((a,b)=>String(b.applyTime).localeCompare(String(a.applyTime)))
    .map(item=>[
      item.no,
      item.type,
      `${item.deviceName}|${item.deviceCode}`,
      `${item.location}|${item.detailLocation}`,
      item.currentDeviceStatus,
      item.applicant,
      item.currentNode,
      item.status,
      item.applyTime
    ]);
}

function syncEquipmentDeviceState(code="", nextStatus="", actionTime="", actionLabel=""){
  const ledgerRow=configs["equipment:设备台账"].rows.find(row=>row[0]===code);
  if(ledgerRow){
    ledgerRow[3]=nextStatus;
    ledgerRow[6]=actionTime || ledgerRow[6];
  }
  const pickerDevice=repairDeviceOptions.find(device=>device.code===code);
  if(pickerDevice)pickerDevice.state=nextStatus;
  if(typeof equipmentLedgerDetailExtras!=="undefined" && equipmentLedgerDetailExtras[code]){
    equipmentLedgerDetailExtras[code].latestAction=actionLabel || equipmentLedgerDetailExtras[code].latestAction;
  }
}

function findEquipmentToggleApplicationByNo(no=""){
  return equipmentToggleApplicationStore.find(item=>item.no===no) || null;
}

