function openInventoryAuditConfirm(action){
  const isPass=action==="审核通过";
  document.querySelector("#opsModalOverlay .modal").className="modal inventory-audit-modal";
  document.getElementById("opsModalTitle").textContent=isPass?"库存盘点审核通过":"库存盘点审核驳回";
  document.getElementById("opsModalBody").innerHTML=`<div class="inventory-audit-confirm">
    <div class="alert ${isPass?"warning":""}"><b>${isPass?"确认提示：":"驳回规则："}</b>${isPass?"审核通过后，系统将以实盘数量更新库存，并按实际分区调整存放位置；不生成入库单、出库单或位置调整单，所有变化将在资产档案变动记录中留痕，确认后不可撤回。":"驳回原因必填，任务状态变为已驳回，盘点范围继续冻结，移动端可修改实盘数量、实际分区和差异原因后重新提交。"}</div>
    <div class="asset-detail-info-grid">
      <div><label>盘点项数</label><b>42</b></div><div><label>盘盈项数 / 总量</label><b>1 / +2</b></div>
      <div><label>盘亏项数 / 总量</label><b>2 / -3</b></div><div><label>位置异常项数</label><b>1</b></div>
      <div><label>预计更新库存数量记录数</label><b>3</b></div><div><label>预计调整分区记录数</label><b>1</b></div>
    </div>
    <div class="form-grid inventory-audit-form">
      <div class="form-field full"><label class="required">${isPass?"通过原因":"驳回原因"}</label><textarea class="control" placeholder="${isPass?"请输入通过原因，最多200字":"请输入驳回原因，最多200字"}"></textarea></div>
    </div>
  </div>`;
  document.getElementById("opsModalConfirm").textContent=isPass?"确认通过":"确认驳回";
  document.getElementById("opsModalOverlay").classList.add("show");
}

