        <thead><tr><th>序号</th><th>工单编号</th><th>设备名称/编码</th><th>安装位置/详细位置</th><th>故障现象</th><th>紧急程度</th><th>提报人/提报时间</th><th>预计关单时间</th><th>工单状态</th><th>操作</th></tr></thead>
