function transferInboundPersonTime(row=[]){
  const people=String(row[3]||"").split(" / ");
  const times=String(row[7]||"").split(" / ");
  const done=row[6]==="已完成";
  return {
    initiator:people[0]||"系统",
    confirmer:done ? (people[1]||"—") : "—",
    createTime:fullInboundTime(times[0]||"—"),
    confirmTime:done ? fullInboundTime(times[1]||"—") : "—"
  };
}

function transferInboundActions(row=[]){
  if(row[6]==="待入库确认") return `<button class="btn text" data-action="确认入库详情">确认入库</button>`;
  return "—";
}

