function receiveApplyActions(row=[]){
  const status=row[7]||"";
  if(status==="待审批") return `<button class="btn text" data-action="审批">审批</button>`;
  if(status==="待申请人确认") return `<button class="btn text" data-action="领用确认">领用确认</button>`;
  return `<span class="text-muted">—</span>`;
}

function receiveApplyStatusTag(status=""){
  const cls={
    "待审批":"pending",
    "待领用出库":"outbound",
    "待申请人确认":"confirm",
    "待调出确认":"confirm",
    "已调出":"outbound",
    "借用中":"neutral",
    "已完成":"done",
    "已驳回":"rejected",
    "已提交":"done",
    "通过":"done",
    "驳回":"rejected",
    "未到达":"neutral"
  }[status]||"neutral";
  return `<span class="tag receive-apply-status ${cls}"><i class="dot"></i>${status||"—"}</span>`;
}

