function outboundMetaFor(row=[]){
  if(outboundMeta[row[0]]) return outboundMeta[row[0]];
  const type=row[1]||"";
  const dept={出库安装:"设备保障部",领用出库:"物业工程部",调拨出库:"资产管理部",临时借用:"安全管理部",报废出库:"设备保障部"}[type]||"—";
  const status=row[8]||"";
  const assetStatus=type==="报废出库"&&status==="已完成"?"已报废出库"
    : type==="出库安装"&&status==="已完成"?"已出库安装"
    : type==="领用出库"&&status==="已完成"?"已领用出库"
    : type==="临时借用"&&status==="借用中"?"借用中"
    : "在库";
  return {
    park:"微冷园区",
    dept,
    purpose:row[5]||"—",
    installLocation:"1#综合楼 / 1F / 变配电室",
    detailAddress:"微冷园区 1#综合楼一层东侧变配电室",
    enableTime:"2026-06-12 09:00",
    usagePlace:"制冷机房",
    expectedUseDate:"2026-06-10",
    receiver:row[3]||"—",
    targetWarehouse:"高风险设备库 / H02",
    transferOutPerson:row[3]||"—",
    transferRequirement:"目标仓库完成入库后流程闭环",
    borrower:row[3]||"—",
    borrowPlace:"消防泵房",
    expectedReturnTime:"2026-06-15 18:00",
    borrowReason:row[5]||"—",
    relatedScrapNo:row[2]||"—",
    disposalPerson:row[3]||"—",
    disposalTime:"—",
    assetStatus,
    approval:row[7]||"—",
    result:`${type||"出库"}当前状态为${row[8]||"—"}。`
  };
}

function outboundDetailTimes(row=[]){
  const [applyTime="",completeTime=""]=String(row[9]||"").split(" / ");
  return {
    apply:fullInboundTime(applyTime||"—"),
    complete:completeTime&&completeTime!=="—"?fullInboundTime(completeTime):""
  };
}

function outboundDetailSummary(row=[],meta={}){
  const wh=splitWarehouseZone(row[4]||"");
  const times=outboundDetailTimes(row);
  const items=[
    ["出库类型",row[1]||"—"],
    ["所属园区",meta.park||"—"],
    ["出库仓库",`${wh.warehouse}${wh.zone&&wh.zone!=="—"?` / ${wh.zone}`:""}`],
    ["申请人 / 部门",`${row[3]||"—"} / ${meta.dept||"—"}`],
    ["来源单据号",row[2]||"—"],
    ["申请时间",times.apply]
  ];
  if(times.complete) items.push(["完成时间",times.complete]);
  return items;
}

function outboundDetailTypeItems(row=[],meta={}){
  const type=row[1]||"";
  const times=outboundDetailTimes(row);
  if(type==="出库安装") return [
    ["出库用途",meta.purpose||"—"],
    ["安装位置",meta.installLocation||"—"],
    ["详细地址",meta.detailAddress||"—"],
    ["启用时间",meta.enableTime||"—"],
    ["责任人",meta.responsiblePerson||row[3]||"—"],
    ["责任部门",meta.dept||"—"]
  ];
  if(type==="领用出库") return [
    ["出库用途",meta.purpose||"—"],
    ["使用地点",meta.usagePlace||"—"],
    ["期望领用日期",meta.expectedUseDate||"—"],
    ["领用人",meta.receiver||row[3]||"—"],
    ["责任部门",meta.dept||"—"],
    ...(times.complete?[["领用完成时间",times.complete]]:[])
  ];
  if(type==="调拨出库") return [
    ["出库用途",meta.purpose||"—"],
    ["目标仓库",meta.targetWarehouse||"—"],
    ["调出确认人",meta.transferOutPerson||row[3]||"—"],
    ["调拨要求",meta.transferRequirement||"—"],
    ...(times.complete?[["调出时间",times.complete]]:[])
  ];
  if(type==="临时借用") return [
    ["借用人",meta.borrower||row[3]||"—"],
    ["责任部门",meta.dept||"—"],
    ["借用地点",meta.borrowPlace||"—"],
    ["预计归还时间",meta.expectedReturnTime||"—"],
    ["借用原因",meta.borrowReason||meta.purpose||"—"],
    ...(times.complete?[["实际出库时间",times.complete]]:[])
  ];
  if(type==="报废出库") return [
    ["报废原因",meta.purpose||"—"],
    ["关联报废申请单",meta.relatedScrapNo||"—"],
    ["处置负责人",meta.disposalPerson||row[3]||"—"],
    ...(times.complete?[["报废出库完成时间",meta.disposalTime&&meta.disposalTime!=="—"?meta.disposalTime:times.complete]]:[])
  ];
  return [["出库用途",meta.purpose||"—"],["责任部门",meta.dept||"—"]];
}

function outboundListTypeInfo(row=[]){
  const meta=outboundMetaFor(row);
  const type=row[1]||"";
  const items=outboundDetailTypeItems(row,meta);
  if(type==="出库安装") return {primary:meta.installLocation||"—",secondary:`启用时间：${meta.enableTime||"—"}`};
  if(type==="领用出库") return {primary:meta.usagePlace||"—",secondary:`期望领用日期：${meta.expectedUseDate||"—"}`};
  if(type==="调拨出库") return {primary:meta.targetWarehouse||"—",secondary:meta.transferRequirement||"—"};
  if(type==="临时借用") return {primary:`借用人：${meta.borrower||row[3]||"—"}`,secondary:`预计归还：${meta.expectedReturnTime||"—"}`};
  if(type==="报废出库") return {primary:`关联报废申请：${meta.relatedScrapNo||"—"}`,secondary:meta.disposalTime&&meta.disposalTime!=="—"?`完成时间：${meta.disposalTime}`:"待报废出库完成"};
  return {primary:items[0]?.[1]||"—",secondary:items[1]?.[1]||"—"};
}

function outboundActions(row=[]){
  const status=row[8]||"";
  const actions=(configs["warehouse:出库管理"].actionMap[status]||[]);
  return actions.length ? actions.map(action=>`<button class="btn text" data-action="${action}">${action}</button>`).join("") : `<span class="text-muted">—</span>`;
}

function outboundTypeTag(type=""){
  const cls={
    "出库安装":"install",
    "领用出库":"receive",
    "调拨出库":"transfer",
    "临时借用":"borrow",
    "报废出库":"scrap"
  }[type]||"default";
  return `<span class="tag outbound-type-tag ${cls}"><i class="dot"></i>${type||"—"}</span>`;
}

function outboundListTable(cfg){
  const total=cfg.rows.length;
  const currentType=outboundTypePages[activeOutboundTypePage]?.type||"出库安装";
  return `<div class="card table-card outbound-card">
    <div class="table-toolbar">
      <div class="table-toolbar-left"><b>出库单据列表</b><span class="tag">${currentType}</span><span class="tag">共 ${total} 项数据</span></div>
      <div class="table-toolbar-right"><button class="btn outbound-flow-btn" data-action="查看出库流程">点我点我</button><button class="btn" data-action="导出出库单据">导出</button><button class="btn primary" data-action="发起出库申请">发起出库申请</button></div>
    </div>
    <div class="table-wrap">
      <table class="outbound-list-table">
        <thead><tr><th>序号</th>${cfg.columns.map(name=>`<th>${name}</th>`).join("")}<th>操作</th></tr></thead>
        <tbody>${cfg.rows.map((row,i)=>{const time=String(row[9]||"").split(" / "), meta=outboundMetaFor(row), typeInfo=outboundListTypeInfo(row), wh=splitWarehouseZone(row[4]);return `<tr data-row="${i}">
          <td>${i+1}</td>
          <td><button class="table-link" data-action="详情">${row[0]}</button></td>
          <td><div class="cell-two-line"><span class="primary-line">${row[3]||"—"}</span><span class="secondary-line">${meta.dept||"—"}</span></div></td>
          <td>${outboundTypeTag(row[1])}</td>
          <td><div class="cell-two-line"><span class="primary-line">${wh.warehouse}</span><span class="secondary-line">${wh.zone==="—"?"全部分区":wh.zone}</span></div></td>
          <td>${row[6]||"—"}</td>
          <td>${row[5]||"—"}</td>
          <td><div class="cell-two-line"><span class="primary-line">${typeInfo.primary||"—"}</span><span class="secondary-line">${typeInfo.secondary||"—"}</span></div></td>
          <td>${receiveApplyStatusTag(row[8]||"—")}</td>
          <td>${fullInboundTime(time[0]||"—")}</td>
          <td class="actions">${outboundActions(row)}</td>
        </tr>`}).join("")}</tbody>
      </table>
    </div>
    <div class="pagination outbound-type-pagination"><span>第 ${activeOutboundTypePage+1} / ${outboundTypePages.length} 页：${currentType}，共 ${total} 项数据</span><button class="page-btn" data-outbound-type-page="${Math.max(0,activeOutboundTypePage-1)}">‹</button>${outboundTypePages.map((item,index)=>`<button class="page-btn ${index===activeOutboundTypePage?"active":""}" data-outbound-type-page="${index}" title="${item.type}">${index+1}</button>`).join("")}<button class="page-btn" data-outbound-type-page="${Math.min(outboundTypePages.length-1,activeOutboundTypePage+1)}">›</button></div>
  </div>`;
}

function renderOutboundPage(cfg){
  const typePage=outboundTypePages[activeOutboundTypePage]||outboundTypePages[0];
  currentCfg={...cfg,rows:typePage.rows,total:typePage.rows.length};
  page.innerHTML=`<div class="outbound-page">${filters(cfg.filters)}${outboundListTable(currentCfg)}</div>`;
}

function outboundAssetRows(row=[]){
  const type=row[1]||"";
  if(type==="领用出库") return [["1","水泵机械密封","暖通设备 / 水泵配件","备品备件库 / B01","2","在库"]];
  if(type==="调拨出库") return [["1","ZC-202606-00188","低压配电柜抽屉单元","综合设备仓库 / A03","1","在库"]];
  if(type==="临时借用") return [["1","ZC-202606-00091","便携式气体检测仪","高风险设备库 / H02","1","借用中"]];
  if(type==="报废出库") return [["1","ZC-202605-00032","冷却塔风机","已出库安装 / 屋面设备区","1","已报废出库"]];
  return [["1","ZC-202606-00128","低压配电柜","综合设备仓库 / A01","1","在库"],["2","ZC-202606-00129","低压配电柜","综合设备仓库 / A01","1","在库"]];
}

function outboundAssetTable(row=[]){
  return `<table class="subtable outbound-detail-table"><thead><tr><th>序号</th><th>设备编码 / 序号</th><th>设备名称</th><th>当前仓库 / 分区</th><th>数量</th><th>设备状态</th></tr></thead><tbody>${outboundAssetRows(row).map(cols=>`<tr>${cols.map((value,i)=>`<td>${i===5?tag(value):value}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
}

function outboundAssetDetail(row=[]){
  const first=outboundAssetRows(row)[0]||[];
  return `<div class="receive-detail-device-panel outbound-detail-device-panel">
    <div class="receive-detail-device-filter">
      <div class="field"><label>设备名称</label><input class="control filter-input" value="${first[2]||""}" placeholder="请输入设备名称"></div>
      <div class="field"><label>设备分类</label><select class="control filter-input"><option>全部</option><option ${/检测仪|工具/.test(first[2])?"selected":""}>检测设备</option><option ${/配电|电柜|电容/.test(first[2])?"selected":""}>供配电设备</option><option ${!/检测仪|工具|配电|电柜|电容/.test(first[2]||"")?"selected":""}>暖通设备</option></select></div>
      <div class="filter-actions"><button class="btn" type="button" data-receive-detail-device-reset>重置</button><button class="btn primary" type="button" data-receive-detail-device-search>查询</button></div>
    </div>
    ${outboundAssetTable(row)}
  </div>`;
}

function outboundDetailTabContent(tab="设备明细",row=[]){
  if(tab==="流程明细") return outboundProcess(row);
  return outboundAssetDetail(row);
}

function outboundProcess(row=[]){
  const status=row[8]||"";
  const type=row[1]||"";
  const isDone=status==="已完成"||status==="借用中";
  const isPending=/待/.test(status);
  const nodes=[
    ["发起申请",row[3]||"—","已提交",fullInboundTime(String(row[9]||"").split(" / ")[0]||"—"),`提交${type}申请。`],
    [type==="领用出库"?"领用出库处理":type==="调拨出库"?"调出确认":"审批处理",type==="领用出库"?"仓库管理员":type==="调拨出库"?"调出仓库负责人":"资产管理负责人",isDone?"已完成":isPending?status:"未到达",isDone?fullInboundTime(String(row[9]||"").split(" / ")[1]||"—"):"待处理",outboundMetaFor(row).result],
    [type==="调拨出库"?"目标仓库入库":"结果生成","系统",isDone?"已完成":"未到达",isDone?fullInboundTime(String(row[9]||"").split(" / ")[1]||"—"):"—",type==="调拨出库"?"目标仓库完成调拨入库后闭环。":"生成资产状态变更和出库记录。"]
  ];
  return `<div class="receive-process-timeline outbound-process">${nodes.map(item=>`<div class="receive-process-node ${/已完成|已提交/.test(item[2])?"done":/待/.test(item[2])?"current":"pending"}">
    <time>${item[3]}</time><i></i><div><b>${item[0]}<span>${receiveApplyStatusTag(item[2])}</span></b><p>处理角色：${item[1]}</p><em>${item[4]}</em></div>
  </div>`).join("")}</div>`;
}

function outboundDetailHtml(row=[]){
  const meta=outboundMetaFor(row);
  const summaryItems=outboundDetailSummary(row,meta);
  const typeItems=outboundDetailTypeItems(row,meta);
  return `<div class="purchase-inbound-detail outbound-detail">
    <div class="purchase-inbound-detail-title">
      <div class="purchase-inbound-detail-title-main"><h3>${row[0]||"—"}</h3></div>
      <span class="purchase-inbound-detail-status">${receiveApplyStatusTag(row[8]||"—")}</span>
    </div>
    <section class="purchase-inbound-detail-summary outbound-detail-summary">
      ${summaryItems.map(item=>`<div><label>${item[0]}</label><b>${item[1]}</b></div>`).join("")}
    </section>
    <section class="receive-apply-purpose-summary outbound-purpose-summary">
      ${typeItems.map(item=>`<div><label>${item[0]}</label><b>${item[1]}</b></div>`).join("")}
    </section>
    <div class="purchase-inbound-detail-tabs">
      ${["设备明细","流程明细"].map((name,i)=>`<button type="button" class="${i===0?"active":""}" data-outbound-detail-tab="${name}">${name}</button>`).join("")}
    </div>
    <div class="purchase-inbound-detail-tab-panel"><div id="outboundDetailTabBody">${outboundDetailTabContent("设备明细",row)}</div></div>
  </div>`;
}

function outboundDetailActions(row=[]){
  const status=row[8]||"";
  if(status==="待审批") return `<button class="btn" data-close="drawer">关闭</button><button class="btn primary" data-action="审批">审批</button>`;
  if(status==="待领用出库") return `<button class="btn" data-close="drawer">关闭</button><button class="btn primary" data-action="领用出库">领用出库</button>`;
  if(status==="待调出确认") return `<button class="btn" data-close="drawer">关闭</button><button class="btn primary" data-action="确认调出">确认调出</button>`;
  if(status==="已调出") return `<button class="btn" data-close="drawer">关闭</button><button class="btn primary" data-action="确认入库">确认入库</button>`;
  if(status==="借用中") return `<button class="btn" data-close="drawer">关闭</button><button class="btn primary" data-action="归还确认">归还确认</button>`;
  return `<button class="btn" data-close="drawer">关闭</button>`;
}

function openOutboundDetail(row=[]){
  activeDrawerPage="出库管理";
  activeDrawerRow=row||configs["warehouse:出库管理"].rows[0];
  const drawer=document.querySelector("#opsDrawerOverlay .drawer");
  drawer.classList.remove("warehouse-detail-drawer","receive-apply-form-drawer","alarm-workorder-detail-drawer","outbound-detail-drawer","outbound-apply-drawer","inventory-check-detail-drawer");
  drawer.classList.add("purchase-inbound-detail-drawer","outbound-detail-drawer");
  document.getElementById("opsDrawerTitle").textContent="出库详情";
  document.getElementById("opsDrawerTabs").innerHTML="";
  document.getElementById("opsDrawerTabs").classList.add("hidden-tabs");
  document.getElementById("opsDrawerBody").innerHTML=outboundDetailHtml(activeDrawerRow);
  document.querySelector("#opsDrawerOverlay .drawer-foot").innerHTML=outboundDetailActions(activeDrawerRow);
  document.getElementById("opsDrawerOverlay").classList.add("show");
}

