function transferInboundConfirmProcessHtml(row=[]){
  const done=row[6]==="已完成";
  const time=transferInboundPersonTime(row);
  const result=done?"已完成":"待入库确认";
  return `<div class="purchase-inbound-process">
    <div class="purchase-inbound-process-item ${done?"done":"current"}">
      <div class="process-node"><b>1</b></div>
      <div class="process-card">
        <div class="process-card-head"><b>目标仓库入库确认</b>${tag(result)}</div>
        <div class="process-card-grid">
          <div><label>处理人</label><span>${time.confirmer}</span></div>
          <div><label>处理时间</label><span>${time.confirmTime}</span></div>
          <div><label>关联调拨出库单</label><span>${row[2]||"—"}</span></div>
          <div><label>确认结果</label><span>${done?"资产仓库 / 分区已更新":"等待目标仓库确认实物接收"}</span></div>
        </div>
      </div>
    </div>
  </div>`;
}

function transferInboundDetailTabContent(tab,row=[]){
  if(tab==="确认流程") return transferInboundConfirmProcessHtml(row);
  return transferInboundAssetDetailHtml(row);
}

function transferInboundDetailActions(row=[]){
  if(row[6]==="待入库确认"){
    return `<button class="btn" data-close="drawer">关闭</button><button class="btn primary" data-action="确认入库">确认入库</button>`;
  }
  return `<button class="btn" data-close="drawer">关闭</button>`;
}

