  if(activeDrawerPage==="库存盘点") return inventoryCheckDetailContent(tab,row);
  if(activeDrawerPage==="检查项模板") return checkTemplateDetailContent(tab,row);
  if(activeDrawerPage==="入库管理"&&tab==="审批记录") return inboundApprovalRecordHtml(row);
