  if(/时间线|更新记录|操作记录|状态记录|处理记录|验收记录|回写记录|审批记录|审批信息|领用确认记录|审批 \/ 确认记录/.test(tab)) return `<div class="timeline"><div class="timeline-item"><time>2026-06-10 13:42</time><b>${tab}：流程记录已更新</b><span>操作人：李明　结果与意见已留痕。</span></div><div class="timeline-item"><time>2026-06-10 10:18</time><b>${tab}：业务动作完成</b><span>操作人：王海　来源单据与状态已同步。</span></div><div class="timeline-item"><time>2026-06-09 16:35</time><b>记录创建</b><span>系统记录初始状态与来源。</span></div></div>`;
  if(/分区列表/.test(tab)) return `<table class="subtable"><thead><tr><th>分区名称</th><th>用途类型</th><th>是否允许高风险设备</th><th>分区负责人</th><th>当前数量</th><th>状态</th><th>操作</th></tr></thead><tbody><tr><td>A01正常库存区</td><td>正常库存区</td><td>否</td><td>王海</td><td>126</td><td>${tag("启用")}</td><td><button class="btn text" data-action="编辑分区">编辑</button><button class="btn text" data-action="停用分区">停用</button></td></tr></tbody></table>`;
