  if(/设备明细/.test(tab)) return `<table class="subtable"><thead><tr><th>设备名称</th><th>设备分类</th><th>当前仓库 / 分区</th><th>当前可用库存</th><th>领用数量</th></tr></thead><tbody><tr><td>水泵机械密封</td><td>暖通设备 / 水泵配件</td><td>综合设备仓库 / A01</td><td>18</td><td>2</td></tr></tbody></table>`;
  if(/资产明细/.test(tab)) return `<table class="subtable"><thead><tr><th>资产编码</th><th>资产名称</th><th>当前仓库 / 分区</th><th>目标信息</th><th>状态</th></tr></thead><tbody><tr><td>ZC-202606-00128</td><td>低压配电柜</td><td>综合设备仓库 / A01</td><td>1#变配电室</td><td>${tag("在库")}</td></tr></tbody></table>`;
