  if(/巡检明细/.test(tab)) return `<table class="subtable"><thead><tr><th>巡检点</th><th>点位类型</th><th>巡检时间</th><th>巡检结果</th><th>巡检人</th><th>巡检工单</th></tr></thead><tbody><tr><td>1#低压配电柜</td><td>设备点位</td><td>06-10 09:32</td><td>${tag("异常")}</td><td>王海</td><td><span class="link">XJ-202606-0046</span></td></tr></tbody></table>`;
