  if(/设备保养明细/.test(tab)) return `<table class="subtable"><thead><tr><th>设备名称</th><th>保养时间</th><th>实际执行人</th><th>保养结果</th><th>保养工单</th><th>工单状态</th></tr></thead><tbody><tr><td>冷冻水泵</td><td>06-10 10:42</td><td>刘洋</td><td>${tag("异常")}</td><td><span class="link">BY-202606-0032</span></td><td>${tag("处理中")}</td></tr></tbody></table>`;
  if(/巡检记录/.test(tab)) return `<table class="subtable"><thead><tr><th>巡检任务编号</th><th>巡检点名称</th><th>巡检时间</th><th>巡检人</th><th>巡检结果</th><th>异常工单号</th><th>工单状态</th></tr></thead><tbody><tr><td>XJRW-202606-018</td><td>1#低压配电柜</td><td>06-10 09:32</td><td>王海</td><td>${tag("异常")}</td><td>XJ-202606-0046</td><td>${tag("处理中")}</td></tr></tbody></table>`;
  if(/保养记录/.test(tab)) return `<table class="subtable"><thead><tr><th>保养任务编号</th><th>任务来源</th><th>检查项模板</th><th>保养时间</th><th>实际执行人</th><th>保养结果</th><th>异常工单号</th><th>工单状态</th></tr></thead><tbody><tr><td>BYRW-202606-012</td><td>计划生成</td><td>水泵月度保养模板</td><td>06-10 10:42</td><td>刘洋</td><td>${tag("异常")}</td><td>BY-202606-0032</td><td>${tag("处理中")}</td></tr></tbody></table>`;
  if(/关联工单/.test(tab)) return `<table class="subtable"><thead><tr><th>工单编号</th><th>工单类型</th><th>来源模块 / 单据</th><th>工单状态</th><th>当前处理人</th><th>预计完成时间</th><th>是否影响设备状态</th><th>回写结果</th></tr></thead><tbody><tr><td>WX-202606-0086</td><td>维修工单</td><td>模块5 / 人工报修</td><td>${tag("处理中")}</td><td>刘洋</td><td>06-11 18:00</td><td>是</td><td>回写成功</td></tr></tbody></table>`;
