  if(/差异处理/.test(tab)) return `<table class="subtable"><thead><tr><th>差异类型</th><th>差异说明</th><th>处理意见</th><th>责任认定</th><th>附件</th></tr></thead><tbody><tr><td>位置不符</td><td>现场位置与台账不一致</td><td>审核后修正安装位置并留痕</td><td>设备保障部</td><td>现场照片 2 张</td></tr></tbody></table>`;
