function repairWorkorderDetailFromRow(row=[]){
  const [code="WX-20260721-0086",deviceText="冷冻水泵|SB-NT-000117",locationText="制冷机房|B1制冷机房冷冻水泵区",fault="运行时出现异常振动，伴随轴承温升偏高",level="紧急",reporterText="周正 / 2026-07-21 10:18",expectedTime="2026-07-22 18:00",state="处理中",handler="刘洋"]=row;
  const [device="冷冻水泵",deviceCode="SB-NT-000117"]=String(deviceText||"").split("|");
  const [installLocation="制冷机房",detailLocation="B1制冷机房冷冻水泵区"]=String(locationText||"").split("|");
  const [reporter="周正",reportTime="2026-07-21 10:18"]=String(reporterText||"").split(" / ");
  const type=device.includes("配电")?"供配电设备 / 配电柜":device.includes("消防")?"消防设备 / 控制柜":device.includes("风机")?"暖通设备 / 风机":"暖通设备 / 水泵";
  const beforeState=state==="待派单"?"—":device.includes("低压")?"停用":"使用中";
  return {
    code,device,deviceCode,installLocation,detailLocation,fault,level,handler:handler==="—"?"待派单":handler,state,type,beforeState,
    currentDeviceState:state==="待派单"?beforeState==="—"?"使用中":beforeState:state==="已完成"?beforeState:"维修中",
    impact:device.includes("配电")?"影响配电柜散热稳定性，需现场核查风扇与温控模块。":device.includes("消防")?"影响消防泵控制柜状态确认，需完成联动测试。":"影响制冷机房连续运行，需停机窗口内完成检查。",
    dispatcher:state==="待派单"?"—":"王海",
    dispatchTime:state==="待派单"?"—":"2026-07-21 11:02",
    dispatchRemark:state==="待派单"?"待设备主管派单":"请按故障现象完成现场检修，并在移动端提交处置结果。",
    reporter,
    reporterDept:"物业工程部",
    reportTime,
    expectedTime
  };
}

function repairWorkorderInfo(detail){
  const handler=detail.handler&&detail.handler!=="—"&&["待接单","处理中"].includes(detail.state)
    ? `${detail.handler} <button class="btn primary alarm-workorder-change-btn" type="button" data-action="换人">换人</button>`
    : detail.state==="待派单"?"—":detail.handler;
  const dispatchRows=[
    [["处理人",handler],["派单人",detail.dispatcher]],
    [["派单说明",detail.dispatchRemark],["派单时间",detail.dispatchTime]],
    [["预计关单时间",detail.expectedTime]]
  ];
  return `<section class="repair-workorder-info-section">
    <div class="alarm-workorder-basic-grid">${dispatchRows.map(row=>row.map(([label,value])=>`<div class="alarm-workorder-basic-item"><label>${label}</label><div>${value}</div></div>`).join("")).join("")}</div>
  </section>`;
}

function repairWorkorderDeviceInfo(detail){
  const rows=[
    ["设备名称",detail.device],["设备编码",detail.deviceCode],["设备类型",detail.type],["所属园区","微冷园区"],
    ["安装位置",detail.installLocation],["详细位置",detail.detailLocation],["当前设备状态",tag(detail.currentDeviceState)],["维修前状态",detail.beforeState],
    ["责任人/部门","刘洋 / 物业工程部"],["最近更新时间","2026-07-21 10:18"]
  ];
  return `<div class="alarm-workorder-basic-grid repair-workorder-device-grid">${rows.map(([label,value])=>`<div class="alarm-workorder-basic-item"><label>${label}</label><div>${value}</div></div>`).join("")}</div>`;
}

function repairWorkorderProcess(detail){
  const accepted=detail.state!=="待派单";
  const handled=/待验收|已完成/.test(detail.state);
  const nodes=[
    [detail.reportTime,"提交工单",detail.reporter,`提交维修工单，状态进入待派单。`],
    [accepted?detail.dispatchTime:"—","派单",accepted?detail.dispatcher:"—",accepted?`派单给${detail.handler}，设备状态回写为维修中。`:"待设备部门派单。"],
    [accepted?(handled?"2026-07-21 16:40":"移动端处理中"):"—","移动端处置",accepted?detail.handler:"—",handled?"处理人在移动端提交维修结果，工单进入待验收。":"处置在移动端进行，处理人到场后提交处理说明、照片和结果。"],
    [detail.state==="已完成"?"2026-07-21 17:26":detail.state==="待验收"?"待验收":"—","验收",detail.state==="已完成"?"王海":detail.state==="待验收"?"设备部门":"—",detail.state==="已完成"?`验收通过，工单已完成。`:"待设备部门验收。"]
  ];
  return `<div class="alarm-workorder-flow repair-workorder-flow">${nodes.map(([time,node,operator,content])=>`<div class="alarm-workorder-flow-item"><time>${time}</time><i></i><div><b>${node}</b><span>${operator}：${content}</span></div></div>`).join("")}</div>`;
}

function repairWorkorderTabContent(tab, detail=repairWorkorderDetailFromRow(activeDrawerRow)){
  if(tab==="设备信息")return repairWorkorderDeviceInfo(detail);
  if(tab==="流程明细")return repairWorkorderProcess(detail);
  return repairWorkorderInfo(detail);
}

function repairWorkorderDrawerFoot(row=activeDrawerRow){
  const detail=repairWorkorderDetailFromRow(row);
  if(detail.state==="待派单")return `<button class="btn" data-close="drawer">关闭</button><button class="btn" data-action="撤销">撤销</button><button class="btn primary" data-action="派单">派单</button>`;
  if(detail.state==="处理中")return `<button class="btn" data-close="drawer">关闭</button>`;
  if(detail.state==="待验收")return `<button class="btn" data-close="drawer">关闭</button><button class="btn primary" data-action="验收">验收</button>`;
  return `<button class="btn" data-close="drawer">关闭</button>`;
}

