function openRepairWorkorderAction(action,row=activeDrawerRow){
  const detail=repairWorkorderDetailFromRow(row||activeDrawerRow);
  if(action==="派单"||action==="换人"){
    const isChange=action==="换人";
    document.querySelector("#opsModalOverlay .modal").className="modal alarm-dispatch-modal repair-workorder-dispatch-modal";
    document.getElementById("opsModalTitle").textContent=isChange?"派单换人":"派单";
    document.getElementById("opsModalBody").innerHTML=`<div class="alarm-dispatch-form">
      <div class="form-grid">
        <div class="form-field"><label>工单编号（只读）</label><input class="control" readonly value="${detail.code}"><span class="form-help">系统自动带出当前维修工单编号，不允许编辑。</span></div>
        ${isChange?`<div class="form-field"><label>原处理人（只读）</label><input class="control" readonly value="${detail.handler}"></div>`:""}
        <div class="form-field"><label class="required">${isChange?"新处理人":"处理人"}（来源：园区员工，必填）</label><input class="control" list="repairDispatchHandlerOptions" placeholder="请输入或选择处理人，支持模糊搜索"><datalist id="repairDispatchHandlerOptions"><option value="刘洋"></option><option value="赵峰"></option><option value="陈凯"></option><option value="王海"></option><option value="暖通维修班组"></option><option value="供配电维修班组"></option></datalist></div>
        <div class="form-field"><label class="required">预计关单时间</label><input class="control" type="text" placeholder="年/月/日 --:--" value="${detail.expectedTime==="—"?"":detail.expectedTime}"></div>
        <div class="form-field"><label>维修前状态（只读）</label><input class="control" readonly value="${detail.currentDeviceState}"></div>
        <div class="form-field full"><label>${isChange?"换人说明（必填）":"派单说明（选填）"}</label><textarea class="control" placeholder="请输入${isChange?"换人说明":"派单说明"}">${isChange?"当前处理人无法继续处理，重新指派维修工单处理人。":"请按设备故障情况完成现场检修，并上传处理结果。"}</textarea></div>
        <div class="form-field"><label>今日值班人（来自排班日历）</label><input class="control" readonly value="刘洋、陈凯、王海"></div>
      </div>
    </div>`;
    document.getElementById("opsModalConfirm").textContent="确认";
    document.getElementById("opsModalOverlay").classList.add("show");
    return;
  }
  if(action==="撤销"){
    document.querySelector("#opsModalOverlay .modal").className="modal repair-workorder-action-modal repair-workorder-cancel-modal";
    document.getElementById("opsModalTitle").textContent="撤销维修工单";
    document.getElementById("opsModalBody").innerHTML=`<div class="repair-action-content">
      ${repairWorkorderActionSummary(detail)}
      <div class="repair-action-warning"><b>撤销后</b><span>工单状态结束，不再进入派单处理；撤销原因将写入操作记录。</span></div>
      <div class="repair-action-form"><label class="required">撤销原因</label><textarea class="control" placeholder="请输入撤销原因，例如误报、重复提报或故障已恢复"></textarea></div>
    </div>`;
    document.getElementById("opsModalConfirm").textContent="确认撤销";
    document.getElementById("opsModalOverlay").classList.add("show");
    return;
  }
  if(action==="验收"){
    document.querySelector("#opsModalOverlay .modal").className="modal repair-workorder-action-modal repair-workorder-acceptance-modal";
    document.getElementById("opsModalTitle").textContent="维修工单验收";
    document.getElementById("opsModalBody").innerHTML=`<div class="repair-action-content">
      ${repairWorkorderActionSummary(detail)}
      <div class="repair-acceptance-result"><label class="required">验收结论</label><div><button type="button" class="active" data-repair-acceptance-result="通过">通过</button><button type="button" data-repair-acceptance-result="不通过">不通过</button></div></div>
      <div class="repair-action-form"><label>验收人</label><input class="control" readonly value="王海"></div>
      <div class="repair-action-form"><label class="required">验收说明</label><textarea class="control" placeholder="请输入现场复核情况、是否恢复运行及遗留问题"></textarea></div>
    </div>`;
    document.getElementById("opsModalConfirm").textContent="确认验收";
    document.getElementById("opsModalOverlay").classList.add("show");
    return;
  }
  if(action==="处理"){
    document.querySelector("#opsModalOverlay .modal").className="modal repair-workorder-action-modal";
    document.getElementById("opsModalTitle").textContent="提交维修结果";
    document.getElementById("opsModalBody").innerHTML=`<div class="repair-action-content">${repairWorkorderActionSummary(detail)}
      <div class="repair-action-form"><label class="required">处理结果说明</label><textarea class="control" placeholder="请输入维修处理过程、结果和遗留问题"></textarea></div>
      <div class="repair-action-form two"><div><label>处理附件</label><div class="repair-workorder-upload"><button type="button">上传附件</button><span>支持现场照片、维修记录</span></div></div><div><label class="required">建议关闭结果</label><select class="control"><option>处理完成</option><option>无法处理</option><option>建议报废</option></select></div></div>
    </div>`;
    document.getElementById("opsModalConfirm").textContent="提交处理结果";
    document.getElementById("opsModalOverlay").classList.add("show");
    return;
  }
  openAction(action);
}

function repairWorkorderActionSummary(detail){
  return `<div class="repair-action-summary">
    <div><label>工单编号</label><b>${detail.code}</b></div>
    <div><label>设备名称/编码</label><b>${detail.device}</b><span>${detail.deviceCode}</span></div>
    <div><label>安装位置</label><b>${detail.installLocation}</b><span>${detail.detailLocation}</span></div>
    <div><label>当前状态</label><b>${detail.state}</b></div>
  </div>`;
}

function repairSelectedDeviceBox(){
  const device=repairDeviceOptions[selectedRepairDeviceIndex]||repairDeviceOptions[0];
  return `<div class="repair-workorder-device-box" id="repairSelectedDeviceBox">
    <div>
      <label>已选设备</label>
      <b>${device.name}</b>
      <span>${device.code} / ${device.type} / ${device.install} / ${device.detail} / 当前状态：${device.state}</span>
    </div>
    <button class="btn" type="button" data-action="选择维修设备">选择设备</button>
  </div>`;
}

function repairDevicePickerTree(){
  const groups=[
    {name:"暖通设备",children:["全部暖通设备","水泵","风机"]},
    {name:"检测设备",children:["全部检测设备","便携检测仪","温湿度记录仪"]},
    {name:"供配电设备",children:["全部供配电设备","配电柜"]},
    {name:"消防设备",children:["全部消防设备","控制柜"]}
  ];
  return `<div class="repair-device-tree">
    <button type="button" class="repair-device-tree-all ${activeRepairDeviceCategory==="全部设备"?"active":""}" data-repair-device-category="全部设备">全部设备</button>
    ${groups.map(group=>`<section class="repair-device-tree-group">
      <button type="button" class="repair-device-tree-parent ${activeRepairDeviceCategory===group.name?"active":""}" data-repair-device-category="${group.name}"><span>▾</span>${group.name}</button>
      <div class="repair-device-tree-children">
        ${group.children.map(child=>`<button type="button" class="${activeRepairDeviceCategory===child?"active":""}" data-repair-device-category="${child}">${child}</button>`).join("")}
      </div>
    </section>`).join("")}
  </div>`;
}

function repairDevicePickerRows(){
  let selectedIndex=activeDevicePickerContext==="scrap" ? selectedScrapDeviceIndex : activeDevicePickerContext==="toggle" ? selectedToggleDeviceIndex : selectedRepairDeviceIndex;
  const baseRows=activeDevicePickerContext==="toggle" ? equipmentToggleEligibleDevices() : repairDeviceOptions;
  const filtered=baseRows.filter(device=>{
    if(activeRepairDeviceCategory==="全部设备")return true;
    if(activeRepairDeviceCategory.startsWith("全部"))return activeRepairDeviceCategory.includes(device.category.replace("设备",""));
    return device.category===activeRepairDeviceCategory || device.subtype===activeRepairDeviceCategory;
  });
  const rows=filtered.length ? filtered : baseRows;
  if(!rows.length){
    if(activeDevicePickerContext==="toggle")selectedToggleDeviceIndex=-1;
    return `<tr><td colspan="6">暂无可选设备</td></tr>`;
  }
  if(!rows.some(device=>repairDeviceOptions.indexOf(device)===selectedIndex)){
    selectedIndex=repairDeviceOptions.indexOf(rows[0]);
    if(activeDevicePickerContext==="scrap")selectedScrapDeviceIndex=selectedIndex;
    else if(activeDevicePickerContext==="toggle")selectedToggleDeviceIndex=selectedIndex;
    else selectedRepairDeviceIndex=selectedIndex;
  }
  return rows.map(device=>{
    const index=repairDeviceOptions.indexOf(device);
    return `<tr class="${index===selectedIndex?"selected":""}" data-repair-device-row="${index}">
      <td><input type="radio" name="repairDevice" data-repair-device-radio="${index}" ${index===selectedIndex?"checked":""}></td>
      <td>${repairWorkorderTwoLineCell(`${device.name}|${device.code}`)}</td>
      <td>${device.type}</td>
      <td>${repairWorkorderTwoLineCell(`${device.install}|${device.detail}`)}</td>
      <td>${tag(device.state)}</td>
      <td>${repairWorkorderTwoLineCell(device.owner.replace(" / ","|"))}</td>
    </tr>`;
  }).join("");
}

function renderRepairDevicePickerTable(){
  const body=document.getElementById("repairDevicePickerRows");
  if(body)body.innerHTML=repairDevicePickerRows();
  const count=document.getElementById("repairDeviceSelectedCount");
  const selectedIndex=activeDevicePickerContext==="scrap" ? selectedScrapDeviceIndex : activeDevicePickerContext==="toggle" ? selectedToggleDeviceIndex : selectedRepairDeviceIndex;
  if(count)count.textContent=`已选择 ${selectedIndex>=0?1:0} 台设备`;
}

