  const plan=/变配电/.test(taskName)?"配电室专项巡检":/制冷机组/.test(taskName)?"制冷机组周巡":/保洁/.test(taskName)?"日常保洁巡检计划":/临时/.test(taskName)?"临时发起":"冷库机房每日巡检";
