function maintenanceWorkorderDetailFromRow(row=[]){
  const [code,deviceText,reporterText,dueTime,state]=row;
  const [device="冷冻水泵",type="暖通设备 / 水泵"]=String(deviceText||"").split("|");
  const [reporter="—",reportTime="—"]=String(reporterText||"").split(" / ");
  const profileMap={
    "待派单":{handler:"—",dispatcher:"—",dispatchTime:"—",remark:"待设备主管派单",deadline:"—"},
    "待接单":{handler:"刘洋",dispatcher:"李明",dispatchTime:"2026-07-21 10:26",remark:"请按保养异常要求现场核查",deadline:dueTime||"—"},
    "处理中":{handler:"刘洋",dispatcher:"李明",dispatchTime:"2026-07-21 10:26",remark:"请按保养异常要求现场核查",deadline:dueTime||"—"},
    "已完成":{handler:"王海",dispatcher:"李明",dispatchTime:"2026-07-20 11:20",remark:"现场已完成处置",deadline:dueTime||"—"}
  };
  const profile=profileMap[state]||profileMap["待派单"];
  return {
    code:code||"BYGD-20260721-006",
    device:device||"冷冻水泵",
    type:type||"暖通设备 / 水泵",
    reporter,
    reportTime,
    dueTime:dueTime||"—",
    state:state||"待派单",
    task:"制冷水泵月保-07月",
    ...profile
  };
}

function maintenanceWorkorderTabContent(tab, detail=maintenanceWorkorderDetailFromRow(activeDrawerRow)){
  if(tab==="流程明细") return `<div class="workorder-process">
    ${detail.state==="已完成"?`<div class="timeline-item"><time>2026-07-21 17:40</time><b>工单完成</b><span>${detail.handler}提交处理结果，工单状态变更为已完成。</span></div>`:""}
    ${["处理中","已完成"].includes(detail.state)?`<div class="timeline-item"><time>2026-07-21 10:45</time><b>接单处理</b><span>${detail.handler}确认接单，工单状态由待接单变更为处理中。</span></div>`:""}
    ${["待接单","处理中","已完成"].includes(detail.state)?`<div class="timeline-item"><time>${detail.dispatchTime}</time><b>派单</b><span>派单人：${detail.dispatcher}；当前处理人：${detail.handler}；工单状态由待派单变更为待接单。</span></div>`:""}
    <div class="timeline-item"><time>${detail.reportTime}</time><b>异常自动生成保养工单</b><span>来源：${detail.task} / ${detail.device}，状态进入待派单。</span></div>
  </div>`;
  const handlerValue=detail.handler&&detail.handler!=="—"&&["待接单","处理中"].includes(detail.state)
    ? `${detail.handler}<button class="btn primary alarm-workorder-change-btn" type="button" data-action="换人">派单换人</button>`
    : detail.handler;
  return `<div class="workorder-base">
    <h3>派单信息</h3><div class="workorder-accept-grid"><div><label>处理人</label><b class="workorder-handler-inline">${handlerValue}</b></div><div><label>派单人</label><b>${detail.dispatcher}</b></div><div><label>补充留言</label><b>${detail.remark}</b></div><div><label>派单时间</label><b>${detail.dispatchTime}</b></div><div><label>处理时限</label><b>${detail.deadline}</b></div></div>
    <h3>保养详情</h3><div class="workorder-maintenance-source"><label>来源保养任务</label><button class="task-point-link" data-nav="保养任务">${detail.task}</button><span>异常结果生成当前保养工单</span></div>
    <div class="workorder-device-card"><div><label>设备名称</label><b>${detail.device}</b></div><div><label>设备编码</label><b>SB-NT-000218</b></div><div><label>设备类型</label><b>${detail.type}</b></div><button class="btn primary" data-maintenance-equipment="${detail.device}" data-maintenance-result="异常">查看设备保养详情</button></div>
    ${detail.state==="已完成"?`<div class="workorder-close-result"><b>完成结果</b><span>已更换机械密封并完成复测，设备运行正常，结果已回写保养任务与设备台账。</span></div>`:""}
  </div>`;
}

function maintenanceWorkorderDrawerFoot(row=activeDrawerRow){
  const detail=maintenanceWorkorderDetailFromRow(row);
  if(detail.state==="待派单")return `<button class="btn" data-close="maintenanceWorkorderDetail">关闭</button><button class="btn primary" data-action="派单">派单</button>`;
  if(detail.state==="待接单"||detail.state==="处理中")return `<button class="btn" data-close="maintenanceWorkorderDetail">关闭</button>`;
  return `<button class="btn primary" data-close="maintenanceWorkorderDetail">确定</button>`;
}

