function maintenancePlanFrequencyPanelHtml(){
  const tips=`<span class="maintenance-frequency-tip"><b>Tips：</b>请在下方选择保养任务的生成时间</span>`;
  if(maintenancePlanFrequency==="每周"){
    const days=["周一","周二","周三","周四","周五","周六","周天"];
    return `<div class="maintenance-frequency-detail">
      ${tips}
      <div class="maintenance-weekdays">${days.map(day=>`<button type="button" class="${maintenancePlanFrequencyState.weekDays.includes(day)?"active":""}" data-maintenance-weekday="${day}">${day}</button>`).join("")}</div>
    </div>`;
  }
  if(maintenancePlanFrequency==="每月"){
    const days=Array.from({length:28},(_,i)=>i+1);
    return `<div class="maintenance-frequency-detail">
      ${tips}
      <div class="maintenance-month-days">${days.map(day=>`<button type="button" class="${maintenancePlanFrequencyState.monthDays.includes(day)?"active":""}" data-maintenance-month-day="${day}">${day}</button>`).join("")}</div>
    </div>`;
  }
  if(maintenancePlanFrequency==="每季度"){
    const quarterMonthOptions=["首月","第二月","第三月"];
    const dayOptions=Array.from({length:31},(_,i)=>`${i+1}号`);
    return `<div class="maintenance-frequency-detail">
      <div class="maintenance-quarter-count"><label class="required">保养次数：</label><input class="plan-control" type="number" min="1" max="12" value="${maintenancePlanFrequencyState.quarterCount}" data-maintenance-quarter-count><span>次 / 每季度</span>${tips}</div>
      <div class="maintenance-quarter-anchors">${maintenancePlanFrequencyState.quarterAnchors.map((anchor,i)=>`<div class="maintenance-quarter-anchor"><select class="plan-control" data-maintenance-quarter-month="${i}">${quarterMonthOptions.map(item=>`<option ${anchor.month===item?"selected":""}>${item}</option>`).join("")}</select><select class="plan-control" data-maintenance-quarter-day="${i}">${dayOptions.map(item=>`<option ${anchor.day===item?"selected":""}>${item}</option>`).join("")}</select></div>`).join("")}</div>
    </div>`;
  }
  const dateOptions=Array.from({length:12},(_,monthIndex)=>{const month=`${monthIndex+1}`.padStart(2,"0");return Array.from({length:31},(_,dayIndex)=>`${month}-${`${dayIndex+1}`.padStart(2,"0")}`);}).flat();
  return `<div class="maintenance-frequency-detail">
    <div class="maintenance-custom-dates">${maintenancePlanFrequencyState.customDates.map((date,i)=>`<div class="maintenance-custom-date-row"><select class="plan-control" data-maintenance-custom-date="${i}">${dateOptions.map(item=>`<option ${date===item?"selected":""}>${item}</option>`).join("")}</select>${maintenancePlanFrequencyState.customDates.length>1&&i>0?`<button type="button" class="btn text action-maintenance-custom-date-delete" data-maintenance-custom-date-delete="${i}">删除</button>`:""}</div>`).join("")}<button type="button" class="maintenance-custom-date-add action-maintenance-custom-date-add">＋ 添加</button></div>
  </div>`;
}

function rerenderMaintenanceFrequencyPanel(){
  const panel=document.querySelector("[data-maintenance-frequency-panel]");
  if(panel)panel.innerHTML=maintenancePlanFrequencyPanelHtml();
}

function normalizeMaintenancePlanFrequencyState(){
  const quarterMonthOptions=["首月","第二月","第三月"];
  maintenancePlanFrequencyState.quarterCount=Math.min(12,Math.max(1,Number(maintenancePlanFrequencyState.quarterCount)||1));
  const selectedQuarterAnchors=(maintenancePlanFrequencyState.quarterAnchors||[]).map(anchor=>({month:quarterMonthOptions.includes(anchor?.month)?anchor.month:"首月",day:/^([1-9]|[12]\d|3[01])号$/.test(anchor?.day||"")?anchor.day:"1号"})).slice(0,maintenancePlanFrequencyState.quarterCount);
  const fillQuarterAnchors=Array.from({length:Math.max(0,maintenancePlanFrequencyState.quarterCount-selectedQuarterAnchors.length)},()=>({month:"首月",day:"1号"}));
  maintenancePlanFrequencyState.quarterAnchors=[...selectedQuarterAnchors,...fillQuarterAnchors];
  maintenancePlanFrequencyState.weekDays=(maintenancePlanFrequencyState.weekDays||[]).filter(day=>["周一","周二","周三","周四","周五","周六","周天"].includes(day));
  maintenancePlanFrequencyState.monthDays=(maintenancePlanFrequencyState.monthDays||[]).filter(day=>day>=1&&day<=28).sort((a,b)=>a-b);
  maintenancePlanFrequencyState.customDates=(maintenancePlanFrequencyState.customDates||[]).filter(date=>/^\d{2}-\d{2}$/.test(date));
  if(!maintenancePlanFrequencyState.customDates.length)maintenancePlanFrequencyState.customDates=["01-01"];
}

function applyMaintenancePlanRowState(row=[]){
  const frequencyText=String(row[3]||"每月").split("|")[0]||"每月";
  maintenancePlanFrequency=frequencyText.startsWith("每周")?"每周":frequencyText.startsWith("每季度")?"每季度":frequencyText.startsWith("自定义")?"自定义":"每月";
  const detail=String(row[3]||"").split("|")[1]||"";
  if(maintenancePlanFrequency==="每周"){
    const weekdays=["周一","周二","周三","周四","周五","周六","周天"];
    maintenancePlanFrequencyState.weekDays=weekdays.filter(day=>detail.includes(day));
    if(!maintenancePlanFrequencyState.weekDays.length)maintenancePlanFrequencyState.weekDays=["周一","周三","周五"];
  }
  if(maintenancePlanFrequency==="每月"){
    const days=[...detail.matchAll(/(\d{1,2})日/g)].map(match=>Number(match[1])).filter(day=>day>=1&&day<=28);
    maintenancePlanFrequencyState.monthDays=days.length?days:[1,15,28];
  }
  if(maintenancePlanFrequency==="每季度"){
    const count=Number(detail.match(/(\d+)\s*次/)?.[1])||3;
    maintenancePlanFrequencyState.quarterCount=count;
  }
  if(maintenancePlanFrequency==="自定义"){
    const dates=[...detail.matchAll(/\d{4}-(\d{2}-\d{2})/g)].map(match=>match[1]);
    maintenancePlanFrequencyState.customDates=dates.length?dates:["01-01","04-01"];
  }
}

function maintenancePlanDateParts(value="2026-06-11 至 2026-12-31"){
  const [startRaw="",endRaw=""]=String(value).split(" 至 ");
  return {start:startRaw.trim()||"2026-06-11",end:endRaw.trim(),longTerm:endRaw.trim()==="长期"};
}

