        <div class="maintenance-selected-table"><table><thead><tr><th>序号</th><th>设备名称</th><th>设备编码</th><th>设备类型</th><th>检查项模板</th><th>操作</th></tr></thead><tbody>${renderMaintenanceSelectedRows()}</tbody></table></div>
