function inspectionRoutePointsFromSummary(summary=""){
  return String(summary).replace(/等\s*\d+\s*个/g,"").split("、").map(item=>item.trim()).filter(Boolean).slice(0,8);
}

const maintenanceInspectionRoutePoints={
  "冷库机房日巡路线":["冷库A区压缩机组-01","冷库A区冷风机-03","低温库温湿度记录仪-02","冷库门封条检查点","制冷机房东侧区域","冷冻水泵-02"],
  "变配电室专项路线":["1#变配电室低压柜-01","1#变配电室电容补偿柜","配电室绝缘工具柜","配电室温湿度计","配电室通道区域","消防泵控制柜"],
  "制冷机组周巡路线":["制冷机组-01","制冷机组-02","冷却塔风机-03","冷冻水泵-01","冷却水泵-02","屋面冷却塔区域"]
};

function maintenanceRouteSelectedPoints(name="",summary=""){
  if(maintenanceInspectionRoutePoints[name])return maintenanceInspectionRoutePoints[name];
  const fromSummary=inspectionRoutePointsFromSummary(summary);
  return fromSummary.length?fromSummary:["冷库A区压缩机组-01","1#变配电室低压柜-01","冷冻水泵-01"];
}

function inspectionRoutePointSummary(name="",countText=""){
  const points=maintenanceRouteSelectedPoints(name,countText);
  const total=String(countText).match(/\d+\s*个/)?.[0]||`${points.length} 个`;
  return `${points.slice(0,3).join("、")}等 ${total}`;
}

