function inspectionRouteSelectedPointNames(){
  return [...document.querySelectorAll("[data-inspection-route-selected-points] [data-selected-point]")]
    .map(item=>item.dataset.selectedPoint)
    .filter(Boolean);
}

function renderInspectionRouteSelectedPoints(names){
  const container=document.querySelector("[data-inspection-route-selected-points]");
  if(!container)return;
  container.innerHTML=names.length
    ? names.map(point=>`<span data-selected-point="${escapeAttr(point)}">${point}<button type="button" class="inspection-route-point-remove" data-remove-point="${escapeAttr(point)}">×</button></span>`).join("")
    : `<em>请选择巡检点</em>`;
}

function syncInspectionRoutePointRows(names){
  const selected=new Set(names);
  const rows=[...document.querySelectorAll(".inspection-route-point-row")];
  rows.forEach(row=>{
    const checked=selected.has(row.dataset.routePointName);
    row.classList.toggle("is-selected",checked);
    const checkbox=row.querySelector("[data-route-point-check]");
    if(checkbox)checkbox.checked=checked;
  });
  const allCheckbox=document.querySelector("[data-route-point-check-all]");
  if(allCheckbox)allCheckbox.checked=rows.length>0&&rows.every(row=>selected.has(row.dataset.routePointName));
}

function updateInspectionRoutePointSelection(pointName,selected){
  if(!pointName)return;
  const next=new Set(inspectionRouteSelectedPointNames());
  if(selected)next.add(pointName); else next.delete(pointName);
  const ordered=[...document.querySelectorAll(".inspection-route-point-row")].map(row=>row.dataset.routePointName).filter(Boolean);
  const sorted=[...next].sort((a,b)=>{
    const ai=ordered.indexOf(a), bi=ordered.indexOf(b);
    if(ai===-1&&bi===-1)return 0;
    if(ai===-1)return 1;
    if(bi===-1)return -1;
    return ai-bi;
  });
  renderInspectionRouteSelectedPoints(sorted);
  syncInspectionRoutePointRows(sorted);
}

function setAllInspectionRoutePointSelection(selected){
  const names=selected?[...document.querySelectorAll(".inspection-route-point-row")].map(row=>row.dataset.routePointName).filter(Boolean):[];
  renderInspectionRouteSelectedPoints(names);
  syncInspectionRoutePointRows(names);
}

function inspectionRouteFormHtml(route=[]){
  const [name="",points="",park="微冷园区",duration=""]=route||[];
  const selectedPoints=maintenanceRouteSelectedPoints(name,points);
  const durationMinutes=Number(String(duration).match(/\d+/)?.[0]||0);
  const durationHours=durationMinutes>=60?Math.floor(durationMinutes/60):"";
  const durationRemainMinutes=durationMinutes>=60?durationMinutes%60:(durationMinutes||"");
  const routePointRows=[
    ["1","冷库A区压缩机组-01","冷库A区机房","制冷设备、重点设备","检查运行声音、油位、压力是否正常"],
    ["2","冷库A区冷风机-03","冷库A区","制冷设备、日常巡检","检查结霜、风机运行和排水情况"],
    ["3","低温库温湿度记录仪-02","低温库","检测设备、日常巡检","核对温湿度显示与平台数据"],
    ["4","1#变配电室低压柜-01","1#变配电室","电气设备、重点设备","检查柜体温升、异味和指示灯状态"],
    ["5","配电室通道区域","1#变配电室","纯区域点位、安全通道","检查通道占用、门禁和消防器材"],
    ["6","冷冻水泵-01","制冷机房","水泵、制冷设备","检查压力、振动、渗漏和运行状态"]
  ];
  const allSelected=routePointRows.every(row=>selectedPoints.includes(row[1]));
  return `<div class="inspection-route-form">
    <section class="inspection-route-top">
      <div class="inspection-route-base-fields">
        <div class="inspection-route-inline-field"><label class="required">所属园区：</label><select class="control" data-route-required>${["微冷园区","海尔西园区"].map(option=>`<option ${option===park?"selected":""}>${option}</option>`).join("")}</select></div>
        <div class="inspection-route-inline-field"><label class="required">巡检路线名称：</label><input class="control" data-route-required value="${escapeAttr(name)}" placeholder="请输入巡检路线名称"></div>
        <div class="inspection-route-inline-field inspection-route-duration-field"><label class="required">预估时间：</label><div class="inspection-route-duration"><input class="control" value="" aria-label="天数"><span>天</span><input class="control" value="${escapeAttr(durationHours)}" aria-label="小时"><span>小时</span><input class="control" value="${escapeAttr(durationRemainMinutes)}" aria-label="分钟"><span>分钟</span></div></div>
        <p class="inspection-route-duration-tip">Tips：预估时间会影响后期巡检任务的闭环时间，请合理填写！</p>
        <div class="inspection-route-inline-field inspection-route-selected-field"><label>所含巡检点：</label><div class="inspection-route-selected-points" data-inspection-route-selected-points>${selectedPoints.map(point=>`<span data-selected-point="${escapeAttr(point)}">${point}<button type="button" class="inspection-route-point-remove" data-remove-point="${escapeAttr(point)}">×</button></span>`).join("")}</div></div>
      </div>
      <p class="inspection-route-page-tip">巡检路线页面中，所有的新增、编辑等都用抽屉进行交互操作，因为涉及到从大量的巡检点中进行筛选，故提供大篇幅操作空间</p>
    </section>
    <section class="inspection-route-picker-section">
      <h3>巡检路线</h3>
      <div class="inspection-route-picker-filter">
        <div class="inspection-route-filter-row"><label>巡检点：</label><input class="control" placeholder="请输入巡检点"><div class="inspection-route-filter-actions"><button class="btn primary" type="button">查询</button><button class="btn" type="button">重置</button></div></div>
        <div class="inspection-route-filter-row"><label>标签：</label><div class="inspection-route-segments">${["全部","制冷设备","电气设备","水泵","检测设备","纯区域点位","重点设备"].map(item=>`<button type="button">${item}</button>`).join("")}</div></div>
        <div class="inspection-route-filter-row"><label>区域：</label><div class="inspection-route-segments inspection-route-area-segments">${["全部","冷库A区","低温库","制冷机房","1#变配电室","屋面设备区","泵房"].map(item=>`<button type="button">${item}</button>`).join("")}</div><span class="inspection-route-multiselect-tip">可多选</span></div>
      </div>
      <div class="table-wrap"><table class="inspection-route-point-preview-table"><thead><tr><th><input type="checkbox" data-route-point-check-all aria-label="全选巡检点" ${allSelected?"checked":""}></th><th>序号</th><th>巡检点</th><th>区域</th><th>标签</th><th>备注</th></tr></thead><tbody>${routePointRows.map(row=>{const checked=selectedPoints.includes(row[1]);return `<tr class="inspection-route-point-row ${checked?"is-selected":""}" data-route-point-name="${escapeAttr(row[1])}"><td><input type="checkbox" data-route-point-check aria-label="选择${escapeAttr(row[1])}" ${checked?"checked":""}></td>${row.map(cell=>`<td>${cell}</td>`).join("")}</tr>`;}).join("")}</tbody></table></div>
      <p class="inspection-route-foot-tip">这里要做到：点击某一行，即选中；</p>
    </section>
  </div>`;
}

