function receiveApplyFormMaterialRows(){
  const rows=[
    ["水泵机械密封","暖通设备 / 水泵配件","备品备件库 / B01","18","2"],
    ["低压配电柜抽屉单元","供配电设备 / 配电柜","综合设备仓库 / A01","3","1"]
  ];
  return rows.map((row,i)=>receiveApplyDeviceDetailRow(row,i+1)).join("");
}

function receiveApplyDeviceDetailRow(row,index){
  const qty=Number(row[4]||1), stock=Number(row[3]||0);
  return `<tr data-receive-detail-row>
    <td>${index}</td><td>${row[0]}</td><td>${row[1]}</td><td>${row[2]}</td><td>${row[3]}</td>
    <td><input class="control" data-receive-qty type="number" min="1" max="${row[3]}" value="${row[4]||1}"></td>
    <td data-receive-check-result>${receiveCheckTag(qty>=1&&qty<=stock)}</td>
  </tr>`;
}

const receiveSelectableDevices = [
  ["冷冻水泵轴承组件","暖通设备 / 水泵配件","备品备件库 / B01","12","1"],
  ["冷却水泵密封圈","暖通设备 / 水泵配件","备品备件库 / B01","9","1"],
  ["便携式气体检测仪","检测设备 / 便携检测仪","高风险设备库 / H02","6","1"],
  ["温湿度记录仪","检测设备 / 温湿度记录仪","综合设备仓库 / A02","5","1"],
  ["电容补偿控制模块","供配电设备 / 配电柜","综合设备仓库 / A03","0","1"],
  ["低压配电柜抽屉单元","供配电设备 / 配电柜","综合设备仓库 / A01","3","1"],
  ["消防泵控制柜继电器","消防设备 / 控制柜","高风险设备库 / H01","8","1"]
];

function receiveDeviceCategoryTree(){
  const map=new Map();
  receiveSelectableDevices.forEach(row=>{
    const [parent,child]=row[1].split(" / ");
    if(!map.has(parent))map.set(parent,new Set());
    map.get(parent).add(child||"未分类");
  });
  return [...map.entries()].map(([parent,children])=>({parent,children:[...children]}));
}

function receiveApplyDevicePickerHtml(){
  const tree=receiveDeviceCategoryTree();
  return `<div class="receive-device-picker">
    <aside class="receive-device-tree">
      <button type="button" class="receive-device-tree-node root active" data-receive-device-category="全部设备" data-receive-device-level="all">全部设备</button>
      ${tree.map(item=>`<div class="receive-device-tree-group open" data-receive-device-group="${item.parent}">
        <button type="button" class="receive-device-tree-node parent" data-receive-device-toggle="${item.parent}"><span class="tree-caret">▾</span>${item.parent}</button>
        <div class="receive-device-tree-children">
          <button type="button" class="receive-device-tree-node child" data-receive-device-category="${item.parent}" data-receive-device-level="parent">全部${item.parent}</button>
          ${item.children.map(child=>`<button type="button" class="receive-device-tree-node child" data-receive-device-category="${item.parent}" data-receive-device-subcategory="${child}" data-receive-device-level="child">${child}</button>`).join("")}
        </div>
      </div>`).join("")}
    </aside>
    <section class="receive-device-panel">
      <div class="receive-device-picker-filter">
        <div class="field"><label>设备名称</label><input class="control filter-input" placeholder="请输入设备名称"></div>
        <div class="field"><label>当前仓库 / 分区</label><select class="control filter-input"><option>全部</option><option>备品备件库 / B01</option><option>综合设备仓库 / A01</option><option>高风险设备库 / H02</option></select></div>
        <div class="filter-actions"><button class="btn" type="button" data-receive-device-reset>重置</button><button class="btn primary" type="button" data-receive-device-search>查询</button></div>
      </div>
      <div class="table-wrap">
        <table class="subtable receive-device-picker-table">
          <thead><tr><th>选择</th><th>设备名称</th><th>设备分类</th><th>当前仓库 / 分区</th><th>当前可用库存</th></tr></thead>
          <tbody>${receiveSelectableDevices.map((row)=>{const [parent,child]=row[1].split(" / ");return `<tr data-receive-device-row data-device-category="${parent}" data-device-subcategory="${child||""}">
            <td><input type="checkbox" data-receive-device-check ${Number(row[3])<=0?"disabled":""}></td>
            <td>${row[0]}</td><td>${row[1]}</td><td>${row[2]}</td><td>${row[3]}</td>
          </tr>`}).join("")}</tbody>
        </table>
      </div>
      <div class="receive-device-picker-actions"><span id="receiveDeviceSelectedCount">已选择 0 台设备</span></div>
    </section>
  </div>`;
}

